export interface KanbanCardData {
    id: string;
    title: string;
    description?: string;
    labels?: {
        label: string;
        color?: string;
    }[];
    assignee?: {
        name: string;
        avatar?: string;
    };
    priority?: 'low' | 'medium' | 'high';
    disabled?: boolean;
    data?: unknown;
}

export interface KanbanColumnData {
    id: string;
    title: string;
    cards: KanbanCardData[];
    color?: string;
    limit?: number;
    disabled?: boolean;
    data?: unknown;
}

export interface KanbanMove {
    cardId: string;
    fromColumnId: string;
    toColumnId: string;
    fromIndex: number;
    toIndex: number;
}

export interface KanbanProps extends Omit<React.ComponentProps<'section'>, 'onChange' | 'defaultValue'> {
    value?: KanbanColumnData[];
    defaultValue?: KanbanColumnData[];
    onValueChange?: (columns: KanbanColumnData[]) => void;
    onCardMove?: (move: KanbanMove) => void;
    onColumnReorder?: (ids: string[]) => void;
    renderCard?: (card: KanbanCardData, column: KanbanColumnData) => React.ReactNode;
    onCardClick?: (card: KanbanCardData) => void;
    disabled?: boolean;
    readOnly?: boolean;
    label?: string;
}

interface KanbanContext {
    direction: 'ltr' | 'rtl';
    columns: KanbanColumnData[];
    disabled: boolean;
    readOnly: boolean;
    move: (cardId: string, columnId: string, index: number) => boolean;
    reorder: (from: number, to: number) => void;
    renderCard: KanbanProps['renderCard'];
    onCardClick: KanbanProps['onCardClick'];
}

export function KanbanColumn({
  column,
  className,
  ...props
}: { column: KanbanColumnData } & React.ComponentProps<'div'>): React.JSX.Element

export function KanbanCard({
  card,
  column,
  className,
  ...props
}: { card: KanbanCardData; column: KanbanColumnData } & React.ComponentProps<'article'>): React.JSX.Element

export function KanbanCardActions({
  card,
  column,
}: {
  card: KanbanCardData
  column: KanbanColumnData
}): React.JSX.Element

export function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  loading = false,
  children,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
    loading?: boolean
  }): React.JSX.Element

export function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>): React.JSX.Element

export function DialogContent({
  className,
  children,
  showCloseButton = true,
  draggable,
  resizable,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
  draggable?: boolean
  resizable?: boolean
}): React.JSX.Element

export function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<'div'> & {
  showCloseButton?: boolean
}): React.JSX.Element

export function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>): React.JSX.Element

export interface UIConfig {
    density: 'comfortable' | 'compact';
    direction: 'ltr' | 'rtl';
    locale: string;
}

export interface ConfigProviderProps extends React.HTMLAttributes<HTMLDivElement> {
    density?: UIConfig['density'];
    direction?: UIConfig['direction'];
    locale?: string;
    accent?: string;
    radius?: number;
}

export function useControllableState<T>({
  value,
  defaultValue,
  onChange,
}: {
  value?: T
  defaultValue: T
  onChange?: (value: T) => void
}): readonly [T, (next: T | ((previous: T) => T)) => void]

