        map,
        folderId: folder,
        path,
        navigate,
        query,
        setQuery,
        view: layout,
        setView,
        sort,
        setSort,
        direction,
        setDirection,
        selected: selection,
        select,
        selectAll: () =>
          setSelected(
            multiple
