                ? [filtered.find((entry) => !entry.disabled)!.id]
                : [],
          ),
        clearSelection: () => setSelected([]),
        filtered,
        pageItems: filtered.slice((currentPage - 1) * size, currentPage * size),
        page: currentPage,
        setPage,
        pages,
        disabled,
        busy,
        operation,
        operationError,
        dialog,
        setDialog: (next) => {
          setOperationError('')
          setDialog(next)
        },
        perform,
        cancel: () => {
          request.current?.abort()
          setBusy(false)
          setMessage(`${operation} cancelled.`)
        },
        open: (entry) => {
          if (disabled || entry.disabled) return
