          else if (onOpen) onOpen(entry)
          else setDialog({ kind: 'info', entries: [entry] })
        },
        callbacks: { onDownload, onCreateFolder, onRename, onMove, onDelete, onUpload },
        accept,
        renderPreview,
      }}
    >
      <section
        {...props}
        data-slot="file-browser"
        aria-label={label}
        aria-busy={busy}
