                  ? c.callbacks.onCreateFolder?.(clean, c.folderId, context)
                  : dialog.kind === 'rename' && entry
                    ? c.callbacks.onRename?.(entry, clean, context)
                    : dialog.kind === 'move'
                      ? c.callbacks.onMove?.(dialog.entries, destination || null, context)
                      : c.callbacks.onDelete?.(dialog.entries, context),
