              >
                Cancel
              </Button>
              <Button
                type="submit"
                variant={dialog.kind === 'delete' ? 'destructive' : 'default'}
                disabled={c.busy || c.disabled}
              >
                {c.busy
                  ? 'Working…'
                  : dialog.kind === 'delete'
                    ? 'Delete'
                    : dialog.kind === 'move'
                      ? 'Move'
                      : dialog.kind === 'create'
                        ? 'Create folder'
                        : 'Save'}
              </Button>
            </DialogFooter>
          </form>
        )}
      </DialogContent>
    </Dialog>
  )
}

