import * as React from 'react'
import {
  EditorContent,
  useEditor,
  useEditorState,
  type Editor,
  type Extensions,
  type JSONContent,
} from '@tiptap/react'
import StarterKit from '@tiptap/starter-kit'
import ImageExtension from '@tiptap/extension-image'
import Placeholder from '@tiptap/extension-placeholder'
import TextAlign from '@tiptap/extension-text-align'
import Highlight from '@tiptap/extension-highlight'
import { TextStyleKit } from '@tiptap/extension-text-style'
import { TableKit } from '@tiptap/extension-table'
import {
  Bold,
  Italic,
  Underline,
  Strikethrough,
  Code,
  Quote,
  List,
  ListOrdered,
  AlignLeft,
  AlignCenter,
  AlignRight,
  Undo2,
  Redo2,
  ImagePlus,
  Link,
  Unlink,
  Highlighter,
  Minus,
  CodeXml,
  Table2,
  RemoveFormatting,
  X,
  Loader2,
  Check,
  RotateCcw,
  Image as ImageIcon,
} from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog'
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from '@/components/ui/dropdown-menu'
import { cn } from '@/lib/utils'
import {
  RichTextUploadAnchors,
  imageUploadAnchors,
  changeImageUploadAnchors,
  richTextURL,
  withUploadSignal,
} from '@/lib/rich-text-uploads'
export type { Editor, JSONContent } from '@tiptap/react'
export interface RichTextImage {
  src: string
  alt?: string
  title?: string
}
export interface ImageUploadOptions {
  signal: AbortSignal
  onProgress: (percent: number) => void
}
export type RichTextImageUploader = (
  file: File,
  options: ImageUploadOptions,
) => Promise<string | RichTextImage>
export interface RichTextUpload {
  id: string
  name: string
  status: 'queued' | 'uploading' | 'done' | 'error' | 'cancelled'
  progress?: number
  error?: string
}
export interface RichTextContent {
  html: string
  json: JSONContent
  text: string
}
export interface RichTextEditorProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  'onChange' | 'defaultValue' | 'children'
> {
  value?: string
  defaultValue?: string
  onValueChange?: (html: string) => void
  onContentChange?: (content: RichTextContent) => void
  onImageUpload?: RichTextImageUploader
  onImageUploaded?: (image: RichTextImage, file: File) => void
  onImageUploadError?: (error: Error, file: File) => void
  imageAccept?: string
  maxImageSize?: number
  maxFiles?: number
  placeholder?: string
  label?: string
  disabled?: boolean
  readOnly?: boolean
  toolbar?: boolean
  minHeight?: number
  maxHeight?: number
  extensions?: Extensions
  onReady?: (editor: Editor | null) => void
  children?: React.ReactNode
}
interface RichTextContextValue {
  editor: Editor | null
  disabled: boolean
  readOnly: boolean
  label: string
  minHeight: number
  maxHeight: number
  uploads: RichTextUpload[]
  uploadFiles: (files: File[], position?: number) => Promise<void>
  cancelUpload: (id: string) => void
  retryUpload: (id: string) => void
  dismissUpload: (id: string) => void
  chooseImages: () => void
  canUpload: boolean
}
const RichTextContext = React.createContext<RichTextContextValue | null>(null)
export function useRichTextEditor() {
  const context = React.useContext(RichTextContext)
  if (!context) throw new Error('Rich text parts must be inside RichTextEditor')
  return context
}
const EditorImage = ImageExtension.extend({
  addAttributes() {
    return {
      ...this.parent?.(),
      alignment: {
        default: 'center',
        parseHTML: (element) => element.getAttribute('data-align') ?? 'center',
        renderHTML: (attrs) => ({
          'data-align': attrs.alignment,
          style: `display:block;max-width:100%;height:auto;margin-left:${attrs.alignment === 'left' ? '0' : 'auto'};margin-right:${attrs.alignment === 'right' ? '0' : 'auto'}`,
        }),
      },
    }
  },
  parseHTML() {
    return [
      {
        tag: 'img[src]',
        getAttrs: (element) =>
          richTextURL((element as HTMLElement).getAttribute('src') ?? '', 'image') ? null : false,
      },
    ]
  },
})
export function RichTextEditor({
  value,
  defaultValue = '<p></p>',
  onValueChange,
  onContentChange,
  onImageUpload,
  onImageUploaded,
  onImageUploadError,
  imageAccept = 'image/png,image/jpeg,image/webp,image/gif,image/avif',
  maxImageSize = 10 * 1024 * 1024,
  maxFiles = 5,
  placeholder = 'Write your story…',
